//! End-to-end parity against the JS oracle. vectors/parity.json is generated by
//! scripts/gen-parity.mjs from Judge Protocol's MIT JS engine run through the
//! same pipeline (with the interface overrides). Each vector carries the exact
//! verdict string the WASM must print, plus the structured expected fields.

use judge_wasm::{evaluate, run};
use serde_json::Value;

const PARITY: &str = include_str!("../vectors/parity.json");

fn vectors() -> Vec<Value> {
    let v: Value = serde_json::from_str(PARITY).expect("parity.json is valid JSON");
    v.as_array().expect("parity.json is an array").clone()
}

fn build_stdin(criteria: &str, deliverable: &str) -> String {
    serde_json::json!({ "criteria": criteria, "deliverable": deliverable }).to_string()
}

#[test]
fn full_verdict_string_matches_the_oracle() {
    let arr = vectors();
    assert!(arr.len() >= 40, "expected >= 40 vectors, got {}", arr.len());
    let mut failures = Vec::new();
    for v in &arr {
        let name = v["name"].as_str().unwrap();
        let criteria = v["criteria"].as_str().unwrap();
        let deliverable = v["deliverable"].as_str().unwrap();
        let want = v["verdict"].as_str().unwrap();
        let got = run(build_stdin(criteria, deliverable).as_bytes());
        if got != want {
            failures.push(format!("[{name}]\n    want: {want}\n    got:  {got}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} vectors mismatched:\n{}",
        failures.len(),
        arr.len(),
        failures.join("\n")
    );
}

#[test]
fn structured_fields_match_the_oracle() {
    let mut failures = Vec::new();
    for v in &vectors() {
        let name = v["name"].as_str().unwrap();
        let criteria = v["criteria"].as_str().unwrap();
        let deliverable = v["deliverable"].as_str().unwrap();
        let exp = &v["expected"];
        let verdict = evaluate(build_stdin(criteria, deliverable).as_bytes());

        let mut problems = Vec::new();
        if verdict.pass != exp["pass"].as_bool().unwrap() {
            problems.push(format!("pass {} != {}", verdict.pass, exp["pass"]));
        }
        if verdict.score != exp["score"].as_i64().unwrap() {
            problems.push(format!("score {} != {}", verdict.score, exp["score"]));
        }
        if verdict.th != exp["th"].as_i64().unwrap() {
            problems.push(format!("th {} != {}", verdict.th, exp["th"]));
        }
        let want_err = exp.get("err").and_then(|e| e.as_str());
        if verdict.err.as_deref() != want_err {
            problems.push(format!("err {:?} != {:?}", verdict.err, want_err));
        }
        let want_checks = exp["checks"].as_array().unwrap();
        if verdict.checks.len() != want_checks.len() {
            problems.push(format!(
                "checks len {} != {}",
                verdict.checks.len(),
                want_checks.len()
            ));
        } else {
            for (got_c, want_c) in verdict.checks.iter().zip(want_checks) {
                if got_c.id != want_c["id"].as_str().unwrap()
                    || got_c.ok != want_c["ok"].as_bool().unwrap()
                {
                    problems.push(format!(
                        "check {:?}/{} != {}/{}",
                        got_c.id, got_c.ok, want_c["id"], want_c["ok"]
                    ));
                }
            }
        }
        if !problems.is_empty() {
            failures.push(format!("[{name}] {}", problems.join("; ")));
        }
    }
    assert!(
        failures.is_empty(),
        "{} vectors mismatched:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The interface promises a browser can recompute `eh` from the printed verdict:
/// take the text before `,"eh":`, append `}`, SHA-256 it. This checks that the
/// printed `eh` is exactly that, for every vector's real output.
#[test]
fn eh_is_recomputable_from_the_printed_verdict() {
    use sha2::{Digest, Sha256};
    for v in &vectors() {
        let name = v["name"].as_str().unwrap();
        let criteria = v["criteria"].as_str().unwrap();
        let deliverable = v["deliverable"].as_str().unwrap();
        let out = run(build_stdin(criteria, deliverable).as_bytes());

        let marker = ",\"eh\":\"";
        let at = out.find(marker).expect("verdict has an eh field");
        let prefix = &out[..at];
        let printed_eh = &out[at + marker.len()..out.len() - 2]; // strip the final `"}`
        let mut body = prefix.to_string();
        body.push('}');
        let digest = Sha256::digest(body.as_bytes());
        let recomputed: String = digest.iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(recomputed, printed_eh, "eh mismatch for [{name}]");
    }
}

/// Every vector's verdict is valid JSON with v == 1 and at most 900 bytes.
#[test]
fn every_verdict_is_valid_json_within_900_bytes() {
    for v in &vectors() {
        let name = v["name"].as_str().unwrap();
        let out = run(build_stdin(
            v["criteria"].as_str().unwrap(),
            v["deliverable"].as_str().unwrap(),
        )
        .as_bytes());
        assert!(out.len() <= 900, "[{name}] verdict is {} bytes", out.len());
        let parsed: Value = serde_json::from_str(&out).expect("verdict parses as JSON");
        assert_eq!(parsed["v"].as_i64(), Some(1), "[{name}] v != 1");
    }
}
